CREATE TABLE IF NOT EXISTS public.user_asset_access (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES public.gps_devices(id) ON DELETE CASCADE, vehicle_id uuid NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, assigned_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, user_id, device_id, vehicle_id));